<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center"
         style="cursor:pointer" @onclick="ToggleExpanded">
        <strong>Change Password</strong>
        <span>@(Expanded ? "▲" : "▼")</span>
    </div>
    @if (Expanded)
    {
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm Password</label>
                <input type="password" class="form-control" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="alert alert-danger">@_error</div>
            }
            @if (_success)
            {
                <div class="alert alert-success">Password updated successfully!</div>
            }

            <button class="btn btn-warning" @onclick="UpdatePassword" disabled="@_updating">
                @(_updating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback OnPasswordChanged { get; set; }

    private bool Expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _error = "";
    private bool _success;
    private bool _updating;

    private void ToggleExpanded() => Expanded = !Expanded;

    private async Task UpdatePassword()
    {
        _error = "";
        _success = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _error = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 6)
        {
            _error = "New password must be at least 6 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _error = "Passwords do not match.";
            return;
        }

        _updating = true;
        await OnPasswordChanged.InvokeAsync();
        _updating = false;
        _success = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }
}
