+                <small class="text-muted d-block mt-2">Last password change: @_lastPasswordChange.Value.ToString("f")</small>
+            }
+        </div>
+
+        <ActiveSessionsTable Sessions="_sessions" CurrentSessionId="session-1" OnRevoke="HandleRevoke" />
+    }
+</div>
+
+@code {
+    private bool _loading = true;
+    private bool _twoFactorEnabled;
+    private DateTime? _lastPasswordChange;
+    private List<ActiveSession> _sessions = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadSettings();
+    }
+
+    private async Task LoadSettings()
+    {
+        _loading = true;
+        var settings = await SettingsService.GetSecuritySettingsAsync();
+        _twoFactorEnabled = settings.TwoFactorEnabled;
+        _lastPasswordChange = settings.LastPasswordChange;
+        _sessions = settings.Sessions;
+        _loading = false;
+    }
+
+    private void Toggle2FA(ChangeEventArgs e)
+    {
+        _twoFactorEnabled = (bool)(e.Value ?? false);
+    }
+
+    private async Task HandlePasswordChanged()
+    {
+        await SettingsService.ChangePasswordAsync("", "");
+        _lastPasswordChange = DateTime.UtcNow;
+    }
+
+    private async Task HandleRevoke(string sessionId)
+    {
+        await SettingsService.RevokeSessionAsync(sessionId);
+        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
+    }
+}
